   589   * This function will return a Bag from the PKCS12 structure.
   590   *
   591   * After the last Bag has been read
   592   * %GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE will be returned.
   593   *
   594   * Returns: On success, %GNUTLS_E_SUCCESS (0) is returned, otherwise a
   595   *   negative error value.
   596   **/
   597  int
   598  gnutls_pkcs12_get_bag(gnutls_pkcs12_t pkcs12,
   599                        int indx, gnutls_pkcs12_bag_t bag)
   600  {
   601          ASN1_TYPE c2 = ASN1_TYPE_EMPTY;
   602          int result, len;
   603          char root2[MAX_NAME_SIZE];
   604          char oid[MAX_OID_SIZE];
   605
   606          if (pkcs12 == NULL) {
   607                  gnutls_assert();
   608                  return GNUTLS_E_INVALID_REQUEST;
   609          }
   610
   611          /* Step 1. decode the data.
   612           */
   613          result = _decode_pkcs12_auth_safe(pkcs12->pkcs12, &c2, NULL);
   614          if (result < 0) {
   615                  gnutls_assert();
   616                  return result;
   617          }
   618
   619          /* Step 2. Parse the AuthenticatedSafe
   620           */
   621
   622          snprintf(root2, sizeof(root2), "?%u.contentType", indx + 1);
   623
   624          len = sizeof(oid) - 1;
   625          result = asn1_read_value(c2, root2, oid, &len);
   626
   627          if (result == ASN1_ELEMENT_NOT_FOUND) {
   628                  result = GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE;
   629                  goto cleanup;
   630          }
   631
   632          if (result != ASN1_SUCCESS) {
   633                  gnutls_assert();
   634                  result = _gnutls_asn2err(result);
   635                  goto cleanup;
   636          }
   637
   638          /* Not encrypted Bag
   639           */
   640
   641          snprintf(root2, sizeof(root2), "?%u.content", indx + 1);
   642
   643          if (strcmp(oid, DATA_OID) == 0) {
   644                  result = _parse_safe_contents(c2, root2, bag);
   645                  goto cleanup;
   646          }
   647
   648          /* ENC_DATA_OID needs decryption */
   649
   650          result = _gnutls_x509_read_value(c2, root2, &bag->element[0].data);
   651          if (result < 0) {
   652                  gnutls_assert();
   653                  goto cleanup;
   654          }
   655
   656          bag->element[0].type = GNUTLS_BAG_ENCRYPTED;
   657          bag->bag_elements = 1;
   658
   659          result = 0;
   660
   661        cleanup:
   662          if (c2)
   663                  asn1_delete_structure(&c2);
   664          return result;
   665  }
